const reservation = $('Yarın Giriş Yapacaklar').item.json;
const apartment = $input.item.json || {};

const guestName = reservation.Guest_Name || 'Misafir';
const firstName = guestName.split(' ')[0];
const apartmentName = reservation.Apartment || 'Dairemiz';
const checkIn = reservation.Check_In;
const checkOut = reservation.Check_Out;
const nights = reservation.Nights || '?';

// Daire bilgileri (Airtable'daki alanlara göre özelleştir)
const wifiName = apartment['WiFi_Name'] || 'EV-WIFI';
const wifiPass = apartment['WiFi_Password'] || '12345678';
const doorCode = apartment['Door_Code'] || 'Kapı şifresini ayrıca iletiyorum';
const address = apartment['Address'] || 'Adres için mesaj atınız';
const checkInTime = apartment['CheckIn_Time'] || '14:00';
const checkOutTime = apartment['CheckOut_Time'] || '11:00';
const parkingInfo = apartment['Parking'] || 'Açık otopark mevcut';
const nearbyInfo = apartment['Nearby'] || '';

const prompt = `Sen Airbnb ev sahibisin. Aşağıdaki bilgilere göre misafire samimi, kişisel ve sıcak bir Türkçe karşılama mesajı yaz. Mesaj 150-200 kelime olsun. Emoji kullan. Airbnb'nin standart mesajlarından farklı, gerçekten özenli hissettirsin.

Misafir Adı: ${firstName}
Daire: ${apartmentName}
Giriş: ${checkIn} saat ${checkInTime}
Çıkış: ${checkOut} saat ${checkOutTime}
Kalış: ${nights} gece
WiFi: ${wifiName} / ${wifiPass}
Kapı Şifresi: ${doorCode}
Adres: ${address}
Otopark: ${parkingInfo}
${nearbyInfo ? 'Yakın noktalar: ' + nearbyInfo : ''}

Mesaj şunları içersin: kişisel selamlama, giriş talimatları, WiFi, önemli notlar, "keyifli bir konaklama" dileği. Airbnb mesajlaşmasına kopyalanmaya hazır olsun.`;

return [{
  json: {
    prompt,
    guestName,
    firstName,
    apartmentName,
    checkIn,
    checkOut,
    nights,
    reservation_kod: reservation.Rezervasyon_Kodu
  }
}];

const aiResponse = $json.choices?.[0]?.message?.content || 'AI mesaj üretemedi.';
const prev = $('AI Prompt Hazırla').item.json;

return [{
  json: {
    aiMessage: aiResponse,
    guestName: prev.guestName,
    firstName: prev.firstName,
    apartmentName: prev.apartmentName,
    checkIn: prev.checkIn,
    nights: prev.nights,
    reservation_kod: prev.reservation_kod
  }
}];

